export const lessons=[
 {id:'abap-m15-senior-authorization',moduleId:'abap-m15',title:'RAP-Berechtigungen durchgängig: DCL, Operationen und negative Tests',minutes:30,
 prerequisites:'CDS-Projektionen, RAP-Verhalten und Rollen-Grundlagen; zwei getrennte Testbenutzer in einer freigegebenen Lernumgebung.',
 objectives:['Lese-, Änderungs- und Serviceberechtigungen getrennt modellieren.','Unbeabsichtigte Rechteausweitung über Projektionen und interne Aufrufe erkennen.','Negative Berechtigungstests mit beobachtbarem Soll-Ergebnis entwerfen.'],
 paragraphs:[
 'Ein Sachbearbeiter darf Belege seines Buchungskreises lesen, aber nur offene Belege ändern. Dafür reichen weder ein ausgeblendeter Fiori-Button noch ein erfolgreicher OData-Serviceaufruf. Trenne Servicezugang, datensatzbezogenes Lesen und erlaubte Änderungen/Aktionen. Die konkrete Rollenpflege unterscheidet sich zwischen klassischen PFCG-Landschaften, S/4HANA Cloud und SAP BTP ABAP environment.',
 'CDS Access Controls in DCL begrenzen den Zugriff auf die jeweilige CDS-Entität. Eine Projektion erbt diese Bedingungen nicht automatisch nur deshalb, weil sie auf einer geschützten View aufbaut. Definiere für den tatsächlich exponierten Zugriff eine passende Access Control, gegebenenfalls mit expliziter Vererbung. Die Annotation authorizationCheck allein formuliert noch keine fachliche Filterbedingung. Direkter Tabellenzugriff ist nicht automatisch durch die DCL einer anderen View geschützt.',
 'RAP Global Authorization prüft instanzunabhängige Rechte, etwa ob ein Benutzer grundsätzlich anlegen darf. Instance Authorization berücksichtigt den Zustand einer Instanz. Eine Prüfung des bestehenden Buchungskreises ist nicht automatisch eine Prüfung eines neu übergebenen Buchungskreises: ein unerlaubter Wechsel muss zusätzlich passend zum Zielzustand abgewehrt werden. Feature Control verbessert die Bedienung, ersetzt aber keine Autorisierung.',
 'IN LOCAL MODE ist ein bewusster interner Zugriff im eigenen Behavior-Kontext und kann Autorisierungs- und Featureprüfungen umgehen. Nutze es nicht als Reparatur für einen 403-Fehler. Prüfe privilegierte Lesepfade, technische Benutzer, Hintergrundjobs und Exporte separat. Ein Test mit dem Entwickler-Admin kann eine fehlende DCL verdecken.'
 ],code:'Lesevertrag: Benutzer A → Buchungskreis 1000, Benutzer B → 2000\nÄnderungsvertrag: eigener Buchungskreis UND Status offen\nDirekter Serviceaufruf: gleiche Regel wie über Fiori\nNegativtest: A liest/ändert Schlüssel aus 2000 → kein Datenleck/keine Änderung\nZielzustand: Wechsel 1000 → 2000 ohne Recht → verweigert',codeLang:'text',
 tip:'Review zuerst den echten Zugriffspfad und die Identität, nicht die Farbe des Buttons. Ein Screenshot der UI ist kein Nachweis einer serverseitigen Rechteprüfung.',
 cases:['Benutzer A liest einen eigenen offenen Beleg und ändert einen erlaubten Text; nur dieser Beleg ändert sich.','Ein eigener bereits gebuchter Beleg bleibt lesbar, eine verbotene Änderungsaktion wird verweigert.','A sendet fremden Schlüssel oder unzulässigen Buchungskreis direkt an den Service; kein fremder Inhalt und keine persistierte Änderung.'],
 quiz:[
 Q('Eine CDS-Projektion exponiert Belege über OData. Nur die darunterliegende Modell-View hat DCL. Welcher Review-Schritt ist erforderlich?',[
 ['Den Filter der Modell-View als automatisch geerbt dokumentieren.','DCL der unteren View schützt die darauf aufgebaute Projektion nicht pauschal.'],['Die exponierte Entität und deren Access Control explizit prüfen.','Die Lesegrenze muss am tatsächlichen Zugriff wirken; explizite Vererbung kann dafür eingesetzt werden.'],['Nur das Entfernen der Fiori-Suchfunktion im Client testen.','Die Suche zu verstecken verhindert direkte Servicezugriffe nicht.']],1,sources.auth),
 Q('Eine RAP-Action ist in Fiori deaktiviert. Ein direkter Request kann sie dennoch unberechtigt ausführen. Was ist die richtige Korrektur?',[
 ['Die serverseitige Autorisierung der Operation ergänzen und negativ testen.','Bedienhinweise sind keine harte Grenze; der Backendpfad muss unberechtigte Operationen verweigern.'],['Den Button zusätzlich aus der Toolbar-Konfiguration entfernen.','Ein zweites UI-Versteck schließt den direkten Request nicht.'],['Den Service mit einem gemeinsamen Admin-Benutzer aufrufen.','Ein Admin-Benutzer verschärft die Rechteausweitung und verdeckt fehlende Prüfungen.']],0,sources.auth),
 Q('Ein Benutzer darf einen Beleg aus Kreis 1000 ändern und übergibt als neuen Kreis 2000. Die Instanzprüfung prüft nur den alten Zustand. Was fehlt?',[
 ['Eine UI-Sortierung nach dem bisherigen Buchungskreis.','Sortierung begrenzt weder Zielwerte noch Zugriffe.'],['Ein Retry mit demselben Request nach der Instanzprüfung.','Wiederholung ergänzt keine Prüfung des neu übergebenen Zustands.'],['Eine passende Prüfung der Berechtigung für den Zielzustand.','Das Recht auf den bestehenden Beleg erlaubt nicht automatisch einen Wechsel in jeden anderen Berechtigungsbereich.']],2,sources.auth)
 ],sourceKeys:['auth']},
 {id:'abap-m12-senior-eml-tests',moduleId:'abap-m12',title:'RAP mit EML testen: Puffer, Save Sequence und echte Fehlernachweise',minutes:35,
 prerequisites:'Managed RAP BO, EML-Grundlagen und ABAP Unit; CDS-/SQL-Test-Doubles im Zielrelease verfügbar.',
 objectives:['Puffererfolg von erfolgreicher Persistierung unterscheiden.','FAILED, REPORTED und MAPPED fachlich auswerten.','BO-Szenariotests von Autorisierungs- und HTTP-Integrationstests abgrenzen.'],
 paragraphs:[
 'Ein Test, der nur prüft, dass MODIFY ENTITIES keinen Dump erzeugt, belegt wenig. EML bearbeitet zunächst den transaktionalen Puffer. Validierungen und späte Fehler können erst in der Save Sequence sichtbar werden. Definiere deshalb vorher den fachlichen Vertrag: Ein gültiger Auftrag wird mit korrekten Werten gespeichert; ein ungültiger Auftrag hinterlässt keine persistierte Instanz.',
 'FAILED benennt fehlgeschlagene Instanzen, REPORTED transportiert Meldungen und MAPPED ordnet temporäre Anlege-IDs den Schlüsseln zu. Eine Meldung kann auch eine Warnung sein; REPORTED ungleich initial ist nicht pauschal ein fehlgeschlagener Save. Prüfe erwartete Meldungsschwere, betroffene Instanz und bei feldbezogenen Meldungen den Feldbezug. Die Responses des Änderungsaufrufs und des Commits sind getrennte Prüfpunkte.',
 'Ein äußerer EML-Consumer oder Szenariotest steuert COMMIT ENTITIES beziehungsweise ROLLBACK ENTITIES. Innerhalb der Behavior-Implementierung gehört diese Transaktionssteuerung dem RAP-Framework; dort nicht eigenmächtig COMMIT WORK oder COMMIT ENTITIES einbauen. Teste fachlichen Zustand nach erfolgreichem Save, nicht nur die Anzahl gemappter Schlüssel.',
 'Das SAP-RAP100-Beispiel isoliert CDS-Lesezugriffe und zusätzliche SQL-Abhängigkeiten mit passenden Test-Doubles. setup leert Testzustand, class_teardown zerstört die Testumgebungen. ROLLBACK ENTITIES verwirft noch nicht gespeicherte Pufferdaten, ist aber kein universelles Undo eines früheren echten Datenbankcommits. Verwende keine produktiven Tabellen als Testfixture. Ein isolierter EML-Test mit internem Zugriff beweist weder Benutzerautorisierung noch HTTP-ETag-Verhalten.'
 ],code:'" Prüfablauf, kein vollständiges ABAP-Programm:\n" 1. CDS-/SQL-Doubles konfigurieren und pro Test zurücksetzen.\n" 2. MODIFY ENTITIES ... FAILED ... REPORTED ... MAPPED ...\n" 3. Erwartete unmittelbare Responses prüfen.\n" 4. Im äußeren Test: COMMIT ENTITIES RESPONSES FAILED ... REPORTED ...\n" 5. Persistierten Fachzustand aus isolierter Umgebung lesen.\n" 6. Separat: ungültigen Datensatz und zwei echte Benutzer testen.',codeLang:'abap',
 tip:'Schreibe zuerst eine Assertion auf den falschen Status oder Betrag und prüfe, ob sie tatsächlich scheitert. Ein grüner Test, der das falsche Feld liest, ist keine Absicherung.',
 cases:['Gültige Instanz erzeugen, Action ausführen und nach Save den erwarteten Status und Betrag prüfen.','Eine gültige Warnung zulassen und anhand der Schwere zeigen, dass nicht jede Meldung einen Fehler bedeutet.','Datum verletzt Save-Validierung: späte Fehlerresponse prüfen und nachweisen, dass keine neue fachliche Instanz gespeichert wurde.'],
 quiz:[
 Q('Ein EML-Test erhält nach CREATE einen gemappten Schlüssel. Die Save-Validierung schlägt später fehl. Welche Aussage trägt der erste Prüfschritt allein?',[
 ['Der vollständige Auftrag wurde bereits dauerhaft gespeichert.','Ein Mapping belegt nicht den Erfolg der späteren Save Sequence.'],['Der Benutzer besitzt alle benötigten OData-Schreibrechte.','Ein internes EML-Mapping prüft nicht sämtliche Service- und Benutzergrenzen.'],['Die frühe Anlegephase lieferte ein Mapping, nicht den Save-Erfolg.','Commitresponses und persistierter Fachzustand sind eigene Nachweise.']],2,sources.tests),
 Q('Nach dem COMMIT ENTITIES eines äußeren Szenariotests ist REPORTED gefüllt, FAILED aber leer. Wie bewertet man den Lauf?',[
 ['Jede vorhandene Meldung als fehlgeschlagenen Commit behandeln.','REPORTED kann auch Informationen oder Warnungen enthalten.'],['Meldungsschwere, Sollvertrag und gespeicherten Zustand prüfen.','Die fachliche Erwartung und Fehlerresponse entscheiden, nicht bloß die Existenz einer Meldung.'],['Alle Meldungen löschen und nur auf den gemappten Schlüssel schauen.','Damit würden relevante Warnungen und fachliche Abweichungen verdeckt.']],1,sources.eml),
 Q('Ein Behavior-Handler soll nach jeder Änderung selbst COMMIT WORK ausführen, damit der Test grün wird. Was ist angemessen?',[
 ['Transaktionshoheit beim Framework lassen und den äußeren Test korrigieren.','Eigenmächtiges Commit im Handler verletzt das RAP-Transaktionsmodell.'],['COMMIT WORK im Handler durch COMMIT ENTITIES im Handler ersetzen.','Auch diese Transaktionssteuerung gehört hier nicht in die Behavior-Implementierung.'],['Den Commit nur bei aktivem Debugger im Handler ausführen.','Das erzeugt abweichendes Laufzeitverhalten statt eines belastbaren Tests.']],0,sources.eml)
 ],sourceKeys:['tests','eml']},
 {id:'abap-m13-senior-side-effects',moduleId:'abap-m13',title:'Fiori Elements V4: Side Effects, Meldungen und sichere Erweiterungen',minutes:30,
 prerequisites:'Fiori Elements List Report/Object Page, OData V4 und RAP-Determinations; SAPUI5-Version und Service-Metadaten bekannt.',
 objectives:['Backend-Neuberechnung und UI-Neuladen unterscheiden.','Side-Effect-Quellen und Ziele aus dem Datenvertrag herleiten.','Unterstützte Extension APIs statt generierter Control-Interna wählen.'],
 paragraphs:[
 'Ein Benutzer ändert Menge von 2 auf 3 bei Einzelpreis 10. Das Backend berechnet den Betrag von 20 auf 30, die Object Page zeigt aber weiter 20. Ursache kann eine fehlende Aktualisierung des betroffenen Feldes sein, nicht eine fehlende Multiplikation. Ein Side Effect beschreibt, welche Repräsentationen nach einer Änderung neu gelesen werden sollen; die Annotation ist nicht selbst die fachliche Berechnung.',
 'Für OData V4 verbinden Side-Effect-Metadaten etwa Quantity als Quelle mit NetAmount als Ziel. Prüfe die tatsächlich ausgelieferten Metadaten und die Unterstützung deiner SAPUI5-/Backendversion. RAP-Side-Effect-Definitionen und lokale XML-Annotationen sind unterschiedliche Wege mit releaseabhängigen Möglichkeiten. CAP-CDS-Syntax aus einem Fiori-Tutorial ist nicht unverändert ABAP CDS. Standard-Side-Effects existieren bereits, zusätzliche Regeln müssen nicht jeden Refresh duplizieren.',
 'Ein ungültiger Wert kann schon an der Clientvalidierung scheitern. Dann wird die Änderung noch nicht an das Backend geschickt und die Neuberechnung wird nicht ausgelöst. Analysiere zuerst den Browser-Network-Tab: PATCH, Batch-Teilantworten, nachfolgende Reads und fachliche Meldungen. HTTP 200 für den äußeren Batch beweist nicht den Erfolg jedes inneren Requests. Backendfehler gehören als verständliche, möglichst feldbezogene Meldungen in den regulären Message Flow.',
 'Erweitere zuerst über Annotationen und Konfiguration, dann über dokumentierte Extension Points, Building Blocks und Controller Extensions. Greife nicht auf private generierte Controller oder zufällige DOM-IDs zu. Die SAP-Learning-Quelle zeigt clientseitige Extensions an einem CAP-Backend; ihre Backendbeispiele werden hier nicht als RAP-Code ausgegeben. Prüfe asynchrone Antworten nach Navigation auf den aktuellen Binding-Kontext, damit Daten von Objekt A nicht auf Objekt B erscheinen.'
 ],code:'Quelle: Quantity geändert\nBackend: NetAmount fachlich neu berechnen\nSide-Effect-Ziel: NetAmount erneut lesen\nClientprüfung fehlgeschlagen: kein PATCH, daher keine Serverneuberechnung\nDiagnose: Batch-Teilantwort → Meldung → Ziel-Read → sichtbarer Wert',codeLang:'text',
 tip:'Kein globales Reload als erste Reparatur. Ein gezielter Refresh erhält Kontext und vermeidet unnötige Reads. Messe Requestzahl und teste verworfene Drafts sowie schnelle Navigation.',
 cases:['Menge 2 → 3: Backendbetrag und sichtbarer Betrag werden 30; gezielter Ziel-Read nachvollziehbar.','Ungültiger Zahlenwert: sichtbare Validierung, kein unbeabsichtigter Serverwrite und keine erfundene Neuberechnung.','Während einer langsamen Erweiterungsabfrage von A nach B navigieren: verspätetes Ergebnis von A überschreibt B nicht.'],
 quiz:[
 Q('Nach einer Mengenänderung berechnet RAP den Betrag korrekt, Fiori zeigt noch den alten Wert. Was prüfst du zuerst?',[
 ['Side-Effect-Ziel, Metadaten und den nachfolgenden Read des Betrags.','Die Backendberechnung ist bereits korrekt; die aktualisierte Repräsentation muss den Client erreichen.'],['Eine zweite unabhängige Preisberechnung im Controller einführen.','Doppelte Fachlogik kann abweichende Ergebnisse und Rundungsfehler erzeugen.'],['Die ETag-Prüfung für alle Schreibrequests der App entfernen.','Nebenläufigkeitsschutz zu entfernen aktualisiert keine Anzeige und riskiert Lost Updates.']],0,sources.sideEffects),
 Q('Im Fiori-V4-Formular verletzt eine Eingabe MaxLength. Es gibt keinen PATCH und kein Side-Effect-Read. Was passt zum Ablauf?',[
 ['Der Side Effect sollte die ungültige Eingabe ohne Server korrigieren.','Side Effects sind keine allgemeine clientseitige Reparaturregel für ungültige Werte.'],['Der Server hat die Eingabe bereits erfolgreich gespeichert.','Ohne gesendeten Schreibrequest folgt aus der UI-Eingabe kein Serverwrite.'],['Die Clientvalidierung hält den Write bis zur Korrektur zurück.','Solange die betroffenen Werte ungültig sind, wird der Backendablauf nicht regulär ausgelöst.']],2,sources.sideEffects),
 Q('Eine Fiori-Erweiterung benötigt einen dokumentierten Edit-Hook. Welche Abhängigkeit ist am tragfähigsten?',[
 ['Die interne generierte Controller-Methode aus dem Debugger kopieren.','Private Implementierungsdetails haben keinen stabilen Erweiterungsvertrag.'],['Die passende öffentliche Controller Extension der Zielversion verwenden.','Ein dokumentierter Hook ist der vorgesehene Vertrag; Verfügbarkeit und Lifecycle werden dennoch geprüft.'],['Eine zufällig beobachtete DOM-ID der Speichern-Schaltfläche fest verdrahten.','Generierte DOM-Struktur ist kein Ersatz für eine unterstützte API.']],1,sources.extensions)
 ],sourceKeys:['sideEffects','extensions']},
 {id:'abap-m14-senior-btp-identity',moduleId:'abap-m14',title:'BTP Connectivity: Destination, Cloud Connector und Benutzeridentität',minutes:30,
 prerequisites:'HTTP, Authentifizierung/Autorisierung und BTP-Subaccount; Architekturübung ohne echte Zugangsdaten möglich.',
 objectives:['Netzweg, Trust und Fachberechtigung getrennt diagnostizieren.','Benutzerweitergabe von technischen Integrationsidentitäten abgrenzen.','BTP Cloud Foundry und ABAP-Communication-Konfiguration nicht vermischen.'],
 paragraphs:[
 'Eine Side-by-Side-App auf BTP erreicht einen internen S/4HANA-Service. Die Destination beschreibt Ziel und Authentifizierungsart; Connectivity und Cloud Connector ermöglichen den kontrollierten Weg ins On-Premise-Netz. Eine grüne Destination-Verbindungsprüfung beweist weder korrekte Endbenutzerzuordnung noch fachliche Rechte. Entitlements, Subaccount, Runtime und Servicebindungen müssen für die konkrete App passen.',
 'Bei Principal Propagation wird die angemeldete Identität entlang einer eingerichteten Vertrauenskette an das Backend weitergegeben. Cloud Connector muss nur notwendige Systeme und Ressourcen freigeben; virtuelle Hosts und Location ID gehören zum Routingvertrag. Das Backend muss die übermittelte Identität korrekt einem Benutzer zuordnen und dessen Rechte prüfen. Eine unkontrollierte Weitergabe des Browser-Bearer-Tokens an irgendeine URL ist keine Principal Propagation.',
 'Interaktive Aktionen können eine Benutzeridentität benötigen; ein nächtlicher Job braucht häufig eine eigens begrenzte technische Identität. OAuth Client Credentials ist nicht automatisch ein Endbenutzerkontext. Wähle Authentifizierungsverfahren anhand des unterstützten API-/Kommunikationsszenarios. SAP BTP ABAP environment verwendet für viele Verbindungen Communication Scenarios, Systems und Arrangements; Destination-Einstellungen einer Cloud-Foundry-App nicht blind auf jede ABAP-Laufzeit übertragen.',
 'Fehlersuche folgt den Grenzen: DNS/Route/Cloud-Connector-Ressource, TLS und Trust, Token/Zertifikat und User-Mapping, Servicezugang, dann Fachrechte. 401/403 sind Hinweise, aber kein eindeutiger Ursachenbeweis; Proxy und Backend können beide antworten. Erfasse zuständiges System, Zeitfenster und bereinigte Korrelations-ID. Tokens, Cookies, private Schlüssel und personenbezogene Payloads gehören nicht in Tickets oder Screenshots.'
 ],code:'Browser → App/Approuter → Destination/Connectivity → Cloud Connector → S/4HANA\nJe Grenze dokumentieren: System, Identität, Trust, erlaubte Ressource\nTest A/B: Backend erkennt jeweils A/B und begrenzt deren Fachzugriff\nJob: separate minimale technische Identität, kein übernommener Admin-Login',codeLang:'text',
 tip:'Stelle vor dem ersten Connectivity-Fix die Frage: Als welcher Benutzer soll die Fachoperation im Backend laufen? Ein technischer Superuser ist keine zulässige Abkürzung für fehlerhaftes Mapping.',
 cases:['Zwei interaktive Testbenutzer werden im Backend unterschiedlich erkannt und erhalten nur ihre erlaubten Belege.','Ein technischer Jobzugang erreicht nur den vorgesehenen Service und besitzt keine allgemeinen Administratorrechte.','Mapping oder Ressourcenfreigabe fehlt: kontrollierter Fehler, lokalisierte Grenze und bereinigtes Diagnoseprotokoll ohne Secrets.'],
 quiz:[
 Q('Der BTP-Destination-Check ist grün, im Backend erscheinen alle Aufrufe als derselbe technische Benutzer. Was ist noch nicht belegt?',[
 ['Dass irgendeine technische Verbindung zum Ziel aufgebaut werden kann.','Ein erfolgreicher Check liefert gerade einen begrenzten Nachweis technischer Erreichbarkeit.'],['Dass individuelle Benutzeridentität und Fachrechte korrekt wirken.','Connectivity-Erfolg und authentischer Endbenutzerkontext sind verschiedene Nachweise.'],['Dass die App überhaupt einen Zielnamen konfigurieren durfte.','Der beobachtete Check beantwortet nicht die fachlich entscheidende Identitätsfrage durch diese Alternative.']],1,sources.connectivity),
 Q('Ein nächtlicher BTP-Job verwendet OAuth Client Credentials. Darf die Anwendung daraus die Identität des zuletzt angemeldeten Sachbearbeiters ableiten?',[
 ['Ja, der letzte Browserlogin bestimmt automatisch jeden Hintergrundjob.','Ein technischer Token übernimmt keinen beliebigen früheren Browserkontext.'],['Ja, wenn der Job denselben Destination-Namen wie die UI benutzt.','Der Name eines Ziels verleiht keine Endbenutzeridentität.'],['Nein, technische Identität und Endbenutzerkontext sind getrennt.','Das unterstützte Authverfahren und der Jobvertrag bestimmen, unter welcher Identität die Operation läuft.']],2,sources.connectivity),
 Q('Cloud-Foundry-Beispielwerte für eine Destination sollen in SAP BTP ABAP environment übernommen werden. Was ist der erste Schritt?',[
 ['Das passende Communication Scenario und die Laufzeitunterstützung prüfen.','ABAP-Kommunikationsartefakte und unterstützte Verfahren richten sich nach dem konkreten Szenario.'],['Das technische Passwort als Konstante in die ABAP-Klasse schreiben.','Hardcodierte Secrets sind kein Ersatz für passende Kommunikationskonfiguration.'],['Alle Backendpfade für den Cloud Connector pauschal freigeben.','Eine breite Netzfreigabe löst weder Laufzeitkompatibilität noch Identitätsvertrag.']],0,sources.connectivity)
 ],sourceKeys:['connectivity']},
 {id:'abap-m14-senior-s4-migration',moduleId:'abap-m14',title:'S/4HANA Custom Code: Migration, Clean Core und messbare Modernisierung',minutes:30,
 prerequisites:'ABAP SQL, ATC und Erweiterungsstrategie; Schwerpunkt ERP → S/4HANA On-Premise/Private Edition, nicht pauschal Public Edition.',
 objectives:['Fachliche Migration und optionale Optimierung getrennt planen.','Nutzungsdaten und ATC-Funde begründet priorisieren.','Wrapper, Released APIs und Upgradeverantwortung unterscheiden.'],
 paragraphs:[
 'SAP HANA ist die Datenbank, SAP S/4HANA das darauf aufbauende ERP-Produkt. Eine Datenbankumstellung allein macht alten Custom Code nicht fachlich kompatibel mit veränderten S/4HANA-Datenmodellen. Ein SELECT kann syntaktisch aktiv sein und dennoch falsche Semantik oder ein ungeeignetes Zugriffsmuster haben. Prüfe Zielrelease und Edition; verfügbare Werkzeuge und erlaubte Erweiterungen sind nicht überall gleich.',
 'Beginne mit einem Inventar und einem aussagekräftigen Nutzungszeitraum, der auch Monats-/Jahresabschluss und seltene Pflichtprozesse berücksichtigt. Kein Aufruf im kurzen Messfenster bedeutet nicht automatisch entbehrlich. Ordne Eigentümer, Abhängigkeiten und geplante Ablösung zu. Nicht mehr benötigter Code wird nur nach freigegebenem Stilllegungsplan entfernt, nicht aufgrund einer einzelnen Statistik.',
 'ATC mit passenden S/4HANA-Prüfungen und Simplification-Inhalten identifiziert Anpassungsbedarf. Behebe Syntaxfehler, wiederhole die Analyse und prüfe Quick Fixes fachlich. Ein grüner ATC-Lauf ist weder ein vollständiger Prozesstest noch ein Performancebeweis. Vergleiche Belegzahlen, Beträge und fachliche Zustände mit einer geprüften Referenz. Modifikationsabgleich und eigentliche Systemkonvertierung gehören in den dafür geregelten Projektablauf.',
 'Nach fachlicher Korrektheit priorisierst du gemessene Hotspots, etwa mit SQL Monitor und der SQL Performance Tuning Worklist in unterstützten klassischen Landschaften. Nicht jeden LOOP reflexartig in AMDP übersetzen. Für neue ABAP-Cloud-Erweiterungen freigegebene APIs verwenden und Release Contract prüfen. Ein kundeneigener Wrapper um eine nicht freigegebene API macht die SAP-API selbst nicht released; in zulässigen klassischen Landschaften bleibt dies eine bewusst verwaltete Ausnahme mit eigener Upgradepflicht.'
 ],code:'Inventar/Nutzung → Owner/Scope → Zielrelease/Simplifications\n→ ATC/Syntax → fachliche Anpassung → Prozessregression\n→ gemessene SQL-Hotspots → gezielte Optimierung → Vergleich Soll/Ist\nAPI-Ausnahme: Grund, erlaubte Laufzeit, Owner, Tests und Ablöseplan',codeLang:'text',
 tip:'Trenne zwei Tickets: „funktional korrekt auf Zielrelease“ und „schneller bei gemessener Last“. Sonst ist bei einer Abweichung unklar, ob Migration oder Optimierung die Ursache ist.',
 cases:['Genutzten Z-Report mit einem releasebezogenen ATC-Fund anpassen und Belegzahlen/Beträge gegen Referenz prüfen.','Report nur am Jahresende genutzt: Eigentümer bestätigt Bedarf trotz leerem Wochenmessfenster.','Wrapper ruft nicht freigegebene API auf: keine falsche Cloud-Freigabe; Ausnahme und zulässige Alternative dokumentieren.'],
 quiz:[
 Q('Ein Z-Report wurde sieben Tage nicht aufgerufen, ist aber für den Jahresabschluss vorgesehen. Was folgt daraus?',[
 ['Report erst nach Prozess-/Ownerprüfung und längerer Nutzungsbewertung stilllegen.','Ein kurzes Messfenster deckt seltene verpflichtende Geschäftsprozesse nicht ab.'],['Report automatisch löschen, weil Nutzungsdaten immer vollständig sind.','Die Beobachtungsdauer kann den relevanten Prozess schlicht verfehlen.'],['Report sofort durch AMDP ersetzen, weil die Nutzung selten ist.','Seltene Nutzung begründet weder Löschung noch eine bestimmte Optimierungstechnik.']],0,sources.migration),
 Q('Nach S/4HANA-Anpassung ist ATC grün. Welcher zusätzliche Nachweis fehlt für die fachliche Abnahme?',[
 ['Dass alle lokalen Variablennamen maximal kurz geschrieben sind.','Namenslänge ist kein Nachweis korrekter Belegverarbeitung.'],['Dass jede SELECT-Anweisung durch eine HANA-Prozedur ersetzt wurde.','Eine pauschale technische Umschreibung beweist keine fachliche Gleichheit.'],['Dass relevante Prozesse und Ergebnisse auf dem Zielrelease stimmen.','Statische Prüfungen ersetzen keine Regression der Geschäftsfunktionen.']],2,sources.migration),
 Q('Ein eigener Wrapper kapselt eine nicht freigegebene SAP-API. Was ist die korrekte Bewertung?',[
 ['Die SAP-API ist dadurch automatisch für ABAP Cloud freigegeben.','Eine Kundenkapselung ändert den Release Contract des SAP-Objekts nicht.'],['Die Kapselung braucht zulässige Laufzeit und eigene Upgradeverantwortung.','Eine erlaubte Ausnahme ist gesondert zu verwalten und nicht mit einem offiziellen Release gleichzusetzen.'],['Der Wrapper beseitigt jeden zukünftigen Regressionstest.','Auch gekapselte Abhängigkeiten können bei einem Upgrade ihr Verhalten ändern.']],1,sources.migration)
 ],sourceKeys:['migration']},
 {id:'abap-m19-senior-restartable-jobs',moduleId:'abap-m19',title:'Application Jobs betreiben: Wiederanlauf, Idempotenz und Application Log',minutes:30,
 prerequisites:'ABAP-Transaktionen, Hintergrundverarbeitung und Fehlerkategorien; freigegebene Job-/Log-APIs des Zielsystems prüfen.',
 objectives:['Jobstatus und fachliches Ergebnis getrennt prüfen.','Persistierten Wiederanlaufpunkt mit atomarer Fachwirkung planen.','Diagnosefähige, datensparsame Logs und einen sicheren Replay-Prozess entwerfen.'],
 paragraphs:[
 'Ein Job verarbeitet 1000 Belege und bricht nach 400 ab. „Noch einmal starten“ ist nur sicher, wenn der Vertrag festlegt, welche Belege bereits wirksam verarbeitet wurden. Ein Job kann technisch beendet sein und fachlich abgewiesene Datensätze enthalten. Umgekehrt kann nach einem Timeout eine externe Buchung bereits erfolgreich sein. Statusfarbe und End-to-End-Fachwirkung sind verschiedene Größen.',
 'Arbeite mit begrenzten Paketen und einem stabilen fachlichen Schlüssel oder einer Versionsmarke. Für rein lokale Verarbeitung müssen Wirkung und Verarbeitungsmarker in derselben geeigneten Transaktion gesichert werden. Ein Marker vor der Wirkung riskiert Verlust, ein ungekoppelter Marker danach Duplikate. Ein Neustart muss bereits verarbeitete Belege erkennen, konkurrierende Läufe dürfen dieselbe Wirkung nicht doppelt ausführen.',
 'Für externe Seiteneffekte brauchst du einen Idempotenzvertrag oder belastbaren Abgleich mit dem Ziel. Ein lokales ROLLBACK nimmt eine fremde Buchung nicht zurück. Transiente Fehler können begrenzt mit Backoff wiederholt werden; fachlich ungültige Belege brauchen Korrektur statt Endlos-Retry. Eine Wiederaufnahme „nach Fehlerstep“ darf keine noch notwendigen fachlichen Voraussetzungen überspringen.',
 'Application Log und Jobmonitoring sollen Lauf-ID, Paket/Objektbezug, Fehlerkategorie, Bearbeitungszahlen und erlaubte nächste Aktion zeigen. Keine kompletten Geschäftspayloads, Tokens oder Passwörter protokollieren; auch Log-Leserechte sind zu begrenzen. Die SAP-Samplequelle zeigt konkrete ältere Interfaces und Scheduling-APIs, deren Unterstützung und zulässige RAP-Phase im Zielrelease geprüft werden müssen. Sie ist kein Beweis, dass jeder gezeigte API-Aufruf in jeder RAP-Phase sicher ist.'
 ],code:'Paket 1: 1..200 → Wirkung + Marker gemeinsam gesichert\nPaket 2: 201..400 → Wirkung + Marker gemeinsam gesichert\nCrash → Neustart überspringt bestätigte Schlüssel\nExterner Timeout → Status beim Ziel mit Idempotenzschlüssel abgleichen\nLog: Lauf-ID, Zähler, Fehlerklasse, bereinigter Objektbezug',codeLang:'text',
 tip:'Teste den Crash zwischen Wirkung und Quittierung gezielt. Ein Job, der nur von Anfang bis Ende erfolgreich läuft, hat seinen Wiederanlaufvertrag noch nicht bewiesen.',
 cases:['Zwei lokale Pakete verarbeiten; Zähler und gesicherte Belegzustände stimmen überein.','Letztes Paket enthält nur einen Beleg; weder Auslassung noch doppelte Verarbeitung durch Pagination.','Crash nach Zielbuchung vor lokaler Quittierung: Abgleich/Idempotenz verhindert zweite Buchung, unsicherer Zustand wird sichtbar.'],
 quiz:[
 Q('Ein Job-Log meldet „Finished“, enthält aber 12 fachlich abgewiesene Belege. Wie meldest du das Ergebnis?',[
 ['Vollständig fachlich erfolgreich, weil der Scheduler grün ist.','Technischer Abschluss löscht keine im Log enthaltenen fachlichen Fehler.'],['Unbekannt, da Logs grundsätzlich keinen Ergebnisbezug haben.','Das bereinigte Log und die gesicherten Zustände liefern durchaus relevante Evidenz.'],['Technisch beendet, mit separat ausgewiesenen fachlichen Ablehnungen.','Betriebsstatus und Fachresultat müssen getrennt nachvollziehbar sein.']],2,sources.monitoring),
 Q('Ein rein lokaler Paketjob speichert einen Erledigt-Marker vor der eigentlichen Belegänderung und stürzt danach ab. Welche Korrektur schützt den Wiederanlauf?',[
 ['Marker und Fachwirkung in derselben geeigneten Transaktion sichern.','Der Neustart darf eine nicht ausgeführte Wirkung nicht irrtümlich als erledigt überspringen.'],['Die Marker früher schreiben und nur den Scheduler häufiger starten.','Das vergrößert das Verlustfenster statt es atomar zu schließen.'],['Alle Protokolle entfernen und jeden Beleg immer erneut buchen.','Ohne Deduplizierung drohen doppelte Wirkungen und fehlende Diagnose.']],0,sources.jobs),
 Q('Ein externer Buchungsaufruf endet im Timeout; das Ziel könnte bereits gebucht haben. Was ist vor einem blinden Retry nötig?',[
 ['Ein lokales ROLLBACK, das auch die fremde Buchung sicher entfernt.','Die lokale Transaktion kontrolliert keine bereits wirksame Buchung des fremden Systems.'],['Idempotenzschlüssel oder verbindlicher Statusabgleich beim Ziel.','Der unsichere Ausgang muss so geklärt werden, dass keine doppelte Fachwirkung entsteht.'],['Ein neues zufälliges Belegkennzeichen für jede Wiederholung.','Ein neuer Schlüssel kann die Deduplizierung umgehen und eine zweite Buchung ermöglichen.']],1,sources.jobs)
 ],sourceKeys:['jobs','monitoring']},
 {id:'abap-m13-senior-launchpad',moduleId:'abap-m13',title:'Fiori Launchpad: Intents, Kataloge und Fehlersuche nach dem Transport',minutes:25,
 prerequisites:'Fiori-App und Service; Schwerpunkt ABAP Launchpad in S/4HANA, Tools in Public Edition/BTP separat prüfen.',
 objectives:['App-Sichtbarkeit, Navigation und Backendberechtigung auseinanderhalten.','Semantic Object/Action und Target Mapping nachvollziehen.','Transportabhängigkeiten und Upgrade-Nachfolger kontrolliert prüfen.'],
 paragraphs:[
 'Die App funktioniert in der lokalen Vorschau, nach Transport erscheint jedoch keine Kachel oder „Navigation target could not be resolved“. Vorschau und produktiver Launchpad-Einstieg sind unterschiedliche Wege. Das Launchpad löst einen Intent aus Semantic Object und Action mit passenden Parametern zu einem Navigationsziel auf. Eine vorhandene UI5-Anwendung allein liefert noch kein korrekt zugeordnetes Target Mapping.',
 'Business-Kataloge stellen rollenbezogenen App-/Navigationsinhalt bereit. Spaces und Pages organisieren die Oberfläche. Diese Struktur ist nicht identisch mit der fachlichen Backendautorisierung. Eine sichtbare Kachel kann an fehlenden Service- oder Datenrechten scheitern; eine ausgeblendete Kachel verhindert keinen direkten API-Aufruf. Der konkrete Rollen- und Content-Lifecycle hängt von Edition und Launchpad-Variante ab.',
 'Vergleiche nach einem Transport mit einem echten Fachbenutzer: Intent/Parameter, Katalog-/Rollenzuordnung, Page, Target Mapping, App-ID/Version, Zielsystemalias und Service. Prüfe UI-Deployment, OData-Service sowie erforderliche Konfiguration als getrennte Abhängigkeiten. Ein Entwickler mit breiten Rechten ist kein repräsentativer Abnahmetest. Cacheinvalidierung erst nach Befund einsetzen, nicht als Universalantwort.',
 'Nach Upgrades können Referenzen gebrochen oder Apps deprecated/obsolete sein. Im unterstützten ABAP Launchpad hilft der Content Manager, Referenzen und Nachfolger zu analysieren. Änderungen in verschiedenen Konfigurations-/Customizing-Scopes können sich entkoppeln. Übernimm Nachfolger samt Page, Services und Rollen kontrolliert; vorhandene kundeneigene Anpassungen nicht unbesehen durch einen Reset überschreiben.'
 ],code:'#SalesOrder-display?SalesOrder=4711\nIntent → passendes Target Mapping → App/Parameter/Zielsystem\nSichtbar? Katalog/Rolle/Page prüfen\nNavigierbar? Intent/Mapping/App prüfen\nDaten erlaubt? Service-/Fachautorisierung prüfen',codeLang:'text',
 tip:'Fordere bei „Fiori geht nicht“ genau drei Angaben: Einstieg/Intent, betroffener Fachbenutzer und erste fehlerhafte Network-Teilantwort. Das trennt Contentprobleme von Servicefehlern.',
 cases:['Fachbenutzer startet den freigegebenen Intent und landet auf dem richtigen Objekt im richtigen Zielsystem.','Zwei Mappings mit unterschiedlichen Pflichtparametern: reproduzierbare, passende Zielauflösung nachweisen.','Nach Transport fehlt eine Mappingreferenz: Konfiguration lokalisieren, ohne pauschale Adminrechte zu vergeben.'],
 quiz:[
 Q('Eine UI5-App läuft in der Vorschau, ihr Launchpad-Intent wird nach Transport nicht aufgelöst. Wo setzt die erste Diagnose an?',[
 ['Bei der Ersetzung aller ABAP-SELECTs durch neue CDS-Views.','Der Fehler liegt bereits vor dem fachlichen Datenzugriff in der Zielauflösung.'],['Bei Intent, Parametern, Target Mapping und zugeordnetem Inhalt.','Die Vorschau beweist die produktive Intentauflösung und Rollenverteilung nicht.'],['Bei der Entfernung aller Backend-Berechtigungsprüfungen.','Fehlendes Target Mapping wird dadurch nicht angelegt; zusätzlich entsteht eine Sicherheitslücke.']],1,sources.launchpad),
 Q('Eine Kachel ist sichtbar, der Service verweigert einen fremden Beleg. Welche Schlussfolgerung passt?',[
 ['Kachel und Fachrechte sind verschiedene Grenzen; Ablehnung kann korrekt sein.','Sichtbarkeit einer Anwendung verleiht kein Recht auf jeden Datensatz.'],['Sichtbarkeit garantiert Vollzugriff auf alle Daten dieser Anwendung.','Katalog-/Oberflächeninhalt ist kein universeller Datensatzberechtigungsnachweis.'],['Der Benutzer muss vorsorglich ein dauerhaftes Adminprofil bekommen.','Breite Zusatzrechte umgehen den Fachvertrag und sind keine Fehlerdiagnose.']],0,sources.auth),
 Q('Nach einem Upgrade meldet der Content Manager eine veraltete App und einen Nachfolger. Was gehört zur Umstellung?',[
 ['Nur die Kachel beschriften; der technische Verweis kann unverändert bleiben.','Ein neuer Text migriert weder Navigation noch Serviceabhängigkeiten.'],['Alle Kundenscopes ohne Prüfung auf SAP-Standard zurücksetzen.','Das kann berechtigte kundeneigene Anpassungen verwerfen.'],['Mapping, Page, Services und Rollen des Nachfolgers gemeinsam prüfen.','Der neue Einstieg muss mit seinen technischen und fachlichen Abhängigkeiten konsistent sein.']],2,sources.launchpad)
 ],sourceKeys:['launchpad','auth']},
 {id:'abap-m11-senior-semantics',moduleId:'abap-m11',title:'CDS-Fachsemantik: Währungen, Einheiten und belastbare Summen',minutes:25,
 prerequisites:'CDS View Entities, Aggregationen und DDIC-Typen; Zielfunktionen für Umrechnung sind releaseabhängig.',
 objectives:['Beträge und Mengen zusammen mit ihrer Referenz modellieren.','Annotation und tatsächliche Umrechnung unterscheiden.','Aggregation und Rundung mit Gegenbeispielen testen.'],
 paragraphs:[
 'Eine Zahl 100 ist ohne Einheit oder Währung fachlich unvollständig. Ein Betrag braucht seine Währungsreferenz, eine Menge ihre Maßeinheit. Für entsprechend typisierte Elemente in CDS View Entities werden diese Referenzen durch Semantics-Annotationen verbunden. Wähle die tatsächlichen projizierten Feldnamen; ein umbenanntes CurrencyCode muss auch in der Referenz korrekt erscheinen.',
 'Die Annotation amount.currencyCode erklärt, zu welchem Währungsfeld der Betrag gehört. Sie rechnet 100 USD nicht in 100 EUR um. Mengen von 10 KG und 5 ST dürfen nicht blind als 15 summiert werden. Entweder nach kompatibler Einheit/Währung gruppieren oder eine definierte Umrechnung mit fachlich passender Dimension und Referenz vornehmen.',
 'Bei Währungsumrechnung sind Zielwährung, Kursdatum, Kurstyp, verfügbare Kurse und Fehlerbehandlung Teil des Vertrags. Datenbanktyp, Währungsdezimalstellen, Berechnungspräzision und Anzeigeformat sind unterschiedliche Ebenen. Vermeide binäre Gleitkommaarithmetik als pauschale Geldstrategie; auch DECIMAL allein entscheidet nicht, wann fachlich gerundet wird. Fehlende Kurse nicht still als 1 behandeln.',
 'Prüfe Zeilengranularität vor der Aggregation: ein Join auf mehrere Texte oder Positionen kann denselben Betrag vervielfachen. DISTINCT ist keine allgemeine Reparatur, weil zwei fachlich verschiedene Positionen denselben Wert haben können. Vergleiche Schlüssel, Anzahl und Summen vor und nach der Erweiterung. Technisch schnelle falsche Summen bleiben fachlich falsch.'
 ],code:"// Fragment in der Elementliste einer vorbereiteten CDS View Entity:\n@Semantics.amount.currencyCode: 'CurrencyCode'\nnet_amount as NetAmount,\ncurrency_code as CurrencyCode,\n@Semantics.quantity.unitOfMeasure: 'QuantityUnit'\nquantity as Quantity,\nquantity_unit as QuantityUnit\n// Deklariert Referenzen; führt keine Umrechnung aus.",codeLang:'cds',
 tip:'Lege für Reviews drei kleine Belege mit verschiedenen Währungen und zwei sprachabhängigen Texten an. Damit werden falsche Summen und Joinvervielfachungen schneller sichtbar als mit hundert gleichartigen Testzeilen.',
 cases:['Zwei EUR-Positionen derselben Granularität ergeben die erwartete EUR-Summe mit korrekter Referenz.','EUR und USD bleiben getrennt oder werden mit festgelegtem Datum/Kurstyp nachvollziehbar konvertiert.','Fehlender Kurs oder vervielfachender Textjoin: kontrollierter Fehler beziehungsweise korrigierte Ergebnismenge statt erfundener Summe.'],
 quiz:[
 Q('Eine View annotiert NetAmount mit CurrencyCode. Eine Zeile enthält USD, die andere EUR. Was bewirkt die Annotation allein?',[
 ['Sie rechnet alle Beträge automatisch in die Anmeldesprache um.','Sprache ist keine Zielwährung und die Annotation führt keine Kursumrechnung aus.'],['Sie ersetzt die Werte implizit durch Beträge in der Hauswährung.','Eine semantische Referenz bestimmt weder Kurs noch Umrechnungsdatum.'],['Sie verknüpft Betrag und Währungsreferenz, ohne Werte umzurechnen.','Für eine gemeinsame Summe ist zusätzlich ein fachlich definierter Umrechnungs- oder Gruppierungsvertrag nötig.']],2,sources.semantics),
 Q('Nach einem Join auf zwei sprachabhängige Texte verdoppelt sich die Belegsumme. Was prüfst du zuerst?',[
 ['Die Join-Kardinalität und Zeilengranularität vor der Aggregation.','Mehrere Texttreffer können die gleichen fachlichen Beträge mehrfach in die Summe aufnehmen.'],['Ob die Betragsanzeige von zwei auf null Nachkommastellen wechselt.','Darstellungspräzision erklärt nicht die systematische Verdopplung der Zeilen.'],['Ob man DISTINCT nur auf dem Betrag als universellen Fix setzen kann.','Gleiche Beträge können zu verschiedenen echten Positionen gehören; DISTINCT kann dann Daten verlieren.']],0,sources.semantics),
 Q('Für eine EUR-Umrechnung fehlt am geforderten Kursdatum der USD-Kurs. Welche Behandlung ist fachlich belastbar?',[
 ['Den fehlenden Kurs still durch 1 ersetzen und die Summe freigeben.','Das erzeugt ohne fachliche Grundlage einen falschen Gegenwert.'],['Den fehlenden Kurs nach festgelegtem Fehlervertrag sichtbar behandeln.','Fallback, Ablehnung oder Nachpflege müssen ausdrücklich vereinbart sein; keine erfundene Umrechnung.'],['Die Währungsannotation entfernen und die Beträge als Stückzahlen summieren.','Die Semantik zu entfernen löst den fehlenden Kurs nicht.']],1,sources.semantics)
 ],sourceKeys:['semantics']}
];

export const updates=[
 {id:'abap-m8-l1',title:'Tabellenschlüssel nach Zugriffsmuster wählen',sourceKeys:['clean'],text:'Sekundärschlüssel kosten Aufbau, Pflege und Speicher. Für eine einmalige kleine Tabelle kann ein linearer Zugriff genügen; bei vielen gezielten Reads lohnt ein passender sortierter oder gehashter Schlüssel. Messe Aufbau plus Reads, nicht nur den warmen Lookup. Ein Table Expression ohne Treffer kann eine Ausnahme auslösen; OPTIONAL ist nur passend, wenn ein Initialwert fachlich wirklich „nicht vorhanden“ ausdrücken darf.',tip:'Im Review vier Zahlen nennen: Zeilen, Reads, Änderungen und Gesamtlaufzeit. „HASHED ist immer schneller“ ist keine belastbare Aussage.',cases:['Viele Reads auf eindeutigem Belegschlüssel mit passendem Schlüssel messen.','Leere Tabelle und fehlenden Schlüssel fachlich unterscheiden.','Doppelte Schlüssel oder unterschlagene Missing-Data-Fälle kontrolliert behandeln.'],quiz:[
 Q('Eine Tabelle wird einmal aufgebaut und nur einmal gelesen. Ein Sekundärschlüssel soll allein wegen schnellerer Lookups ergänzt werden. Was misst du?', [['Nur den schnellsten warmen Lookup ohne jeden Aufbau.','Das unterschlägt die Kosten, die bei diesem Zugriffsmuster wesentlich sein können.'],['Aufbau, Pflege, Speicher und vollständige Verarbeitung.','Das Gesamtzugriffsmuster bestimmt, ob der zusätzliche Schlüssel sinnvoll ist.'],['Nur die Länge der Tabellennamen im Debugger.','Namenslänge liefert keinen Leistungsnachweis.']],1,sources.clean),
 Q('Ein fehlender Preiseintrag wird mit OPTIONAL zum Initialwert 0. Fachlich bedeutet 0 aber „kostenlos“. Was ist angemessen?', [['Existenz explizit prüfen und fehlende Preise separat behandeln.','Nicht vorhanden und tatsächlich kostenlos sind unterschiedliche fachliche Zustände.'],['Jeden fehlenden Eintrag als garantierten Gratispreis verbuchen.','Damit wird ein Datenfehler still zur fachlichen Preisentscheidung.'],['OPTIONAL durch einen größeren numerischen Datentyp ersetzen.','Ein anderer Typ unterscheidet die beiden Zustände nicht automatisch.']],0,sources.clean)]},
 {id:'abap-m9-l2',title:'SQL-Hotspots mit repräsentativen Zugriffen belegen',sourceKeys:['migration','clean'],text:'Prüfe erst Ergebnisgleichheit, dann SQL-Anzahl, gelesene Zeilen, übertragene Daten und Laufzeit bei repräsentativen Selektionswerten. Ein kleiner Entwicklerbestand kann einen schlechten Plan verbergen. SQL Monitor und passende Trace-/Planwerkzeuge haben unterschiedliche Reichweite; Verfügbarkeit hängt von Edition und Berechtigungen ab. Bei Messungen produktive Last, Datenschutz und Freigabe beachten.',tip:'Ein einzelner schneller Lauf beweist keinen belastbaren Gewinn. Dokumentiere Datenvolumen, Selektivität, Wiederholungen und das tatsächlich verwendete Werkzeug.',cases:['Hotspot vor/nach Änderung mit gleichem Ergebnis vergleichen.','Leere und sehr breite Selektion getrennt messen.','Joinänderung liefert mehr Zeilen: Optimierung zurück zur Semantikprüfung, nicht Ergebnisabweichung ignorieren.'],quiz:[
 Q('Ein neuer Join läuft schneller, liefert aber 30 statt 20 Belege. Wie bewertest du die Optimierung?', [['Als gelungen, weil allein die niedrigere Laufzeit entscheidend ist.','Eine veränderte Ergebnismenge verletzt ohne fachliche Begründung den Vertrag.'],['Als korrekt, wenn die UI nur die ersten 20 Zeilen anzeigt.','Clientseitige Begrenzung repariert keine falsche Datenmenge.'],['Zuerst Ergebnisgleichheit und Joinsemantik klären.','Geschwindigkeit wird erst bei fachlich korrekter Verarbeitung sinnvoll verglichen.']],2,sources.migration),
 Q('Ein SQL-Plan ist auf zehn Testzeilen schnell. Welcher nächste Nachweis ist für die Hotspotentscheidung relevant?', [['Alle Abfragen vorsorglich in native SQL-Prozeduren umschreiben.','Pauschale Umschreibung ersetzt keine Messung und kann Wartung erschweren.'],['Repräsentative Datenmengen und Selektionswerte samt Ergebnissen messen.','Datenverteilung und Zugriffsmuster beeinflussen die tatsächliche Laufzeit.'],['Den schnellsten Messwert als garantierte Produktionslatenz veröffentlichen.','Ein Einzelwert in anderer Umgebung ist keine solche Garantie.']],1,sources.migration)]},
 {id:'abap-m11-l1',title:'Virtuelle Elemente ohne N+1-Falle',sourceKeys:['extensions','clean'],text:'Eine virtuelle Berechnung pro Listenzeile kann hunderte Einzelreads oder Remote Calls auslösen. Bündele geeignete Zugriffe, beschränke angeforderte Felder und wähle für filter-/sortierbare Fachwerte eine passende Modellierung statt sie nur im UI nachzurechnen. Eine paginierte Liste enthält nicht alle Datensätze: ein globaler fachlicher Status kann nicht zuverlässig aus den gerade geladenen Zeilen abgeleitet werden.',tip:'Im Network-/SQL-Protokoll nicht nur Laufzeit, sondern Zahl der Calls zählen. Eine Seite mit zehn Zeilen kann bei hundert Zeilen ganz anders skalieren.',cases:['Status für mehrere sichtbare Zeilen mit gebündeltem Zugriff bestimmen.','Pagination lädt nur erste Seite: globale Aussage serverseitig aus vollständigem berechtigtem Bestand ableiten.','Remote Dienst fällt aus: kein erfundener grüner Status pro Zeile.'],quiz:[
 Q('Eine Fiori-Liste lädt zehn von hundert Buchungen. Der Controller findet unter den zehn keine offene Buchung. Was kann er sicher sagen?', [['Keine der gerade geladenen Buchungen ist offen.','Der geladene Ausschnitt erlaubt keine Aussage über die übrigen neunzig.'],['Keine Buchung des Kunden ist irgendwo offen.','Paging macht die geladene Liste zu einem unvollständigen Ausschnitt.'],['Der Backendservice hat alle hundert Buchungen verworfen.','Dafür gibt es im beschriebenen Ergebnis keinen Nachweis.']],0,sources.extensions),
 Q('Ein virtuelles Statusfeld erzeugt für jede Listenzeile einen einzelnen Remote Call. Was ist eine sinnvolle Reviewrichtung?', [['Für jede neue Spalte dieselben Einzelcalls zusätzlich ausführen.','Das verstärkt die lineare Zahl teurer Netzaufrufe.'],['Das Timeout entfernen, damit jede Zeile unbegrenzt warten darf.','Unbegrenztes Warten löst weder Last noch Fehlerbehandlung.'],['Zugriffe bündeln und fachlich passende serverseitige Berechnung prüfen.','Das adressiert die N+1-Struktur statt nur ihre Symptome zu verstecken.']],2,sources.clean)]},
 {id:'abap-m12-l1',title:'Draft ist kein persistierter Geschäftsabschluss',sourceKeys:['eml','concurrency'],text:'Ein gespeicherter Draft ist ein Bearbeitungszustand, kein Belegabschluss. Aktivierung kann an Validierung, Berechtigung oder geändertem Aktivzustand scheitern. Prüfe Draft-Verwerfen, Wiederaufnahme und parallele Benutzer. Entitätsschlüssel allein können Draft und aktive Instanz nicht in jedem Kontext unterscheiden; die RAP-Transaktionsschlüssel und der Draftindikator gehören zum korrekt typisierten Zugriff.',tip:'Für die Abnahme drei Ansichten unterscheiden: sichtbarer Entwurf, transaktionaler Puffer und persistierter Aktivzustand. Nicht jedes erfolgreiche Autosave ist eine erfolgreiche Aktivierung.',cases:['Draft ändern und kontrolliert aktivieren, danach Aktivzustand prüfen.','Draft verwerfen: Aktivdaten bleiben unverändert.','Aktivierung ungültigen Drafts scheitert ohne falsche Erfolgsmeldung.'],quiz:[
 Q('Fiori bestätigt das Speichern eines Drafts. Die Aktivierungsvalidierung lehnt den Beleg später ab. Was ist korrekt?', [['Autosave beweist bereits den erfolgreichen Geschäftsabschluss.','Draftspeicherung und Aktivierung haben verschiedene fachliche Bedeutung.'],['Der Entwurf kann existieren, ohne dass der Aktivbeleg erfolgreich geändert wurde.','Die fehlgeschlagene Aktivierung muss getrennt ausgewertet werden.'],['Der Client darf die Aktivierung dann ohne Validierung erzwingen.','Die Validierung schützt die fachliche Konsistenz und darf nicht umgangen werden.']],1,sources.eml),
 Q('Ein Test verwirft einen bearbeiteten Draft. Welcher Soll-Nachweis passt?', [['Der aktive Beleg wird automatisch vollständig gelöscht.','Draftverwerfen ist kein Löschauftrag für den Aktivbeleg.'],['Alle anderen Benutzer verlieren unabhängig vom Beleg ihre Sitzung.','Das ist keine reguläre Folge des Draftverwerfens.'],['Die verworfene Änderung erscheint nicht im unveränderten Aktivzustand.','Der Entwurf und der aktive Fachzustand werden getrennt behandelt.']],2,sources.eml)]},
 {id:'abap-m12-l2',title:'ETag-Konflikte nicht mit blindem Retry umgehen',sourceKeys:['concurrency'],text:'Ein ETag schützt vor Änderungen auf veraltetem Stand; ein Lock schützt die kritische gleichzeitige Bearbeitung. Kein Mechanismus ist pauschal Ersatz für den anderen. Teste über den echten OData-Pfad mit zwei Clients. Nach einem Konflikt neu lesen und fachlich entscheiden, ob Eingaben zusammengeführt oder verworfen werden. Ein Retry mit absichtlich ausgeschalteter Vorbedingung wäre eine stille Überschreibung.',tip:'Teste auch Änderungen an abhängigen Entitäten und die im Zielrelease relevante Total-ETag-/Draft-Konfiguration. Ein nur in der UI angezeigter Zeitstempel belegt keine wirksame Vorbedingung.',cases:['Aktuelle Version schreiben und neue Version lesen.','Zweiter Client sendet alte Version: kontrollierter Konflikt.','Konfliktbehandlung überschreibt nicht automatisch die erste Änderung.'],quiz:[
 Q('Zwei OData-Clients lesen Version A. Nach dem Save von Client 1 schreibt Client 2 mit A. Was ist bei wirksamem ETag-Schutz zu erwarten?', [['Die veraltete Änderung wird als Konflikt zurückgewiesen.','Der zweite Client basiert nicht mehr auf dem aktuellen Zustand.'],['Client 2 überschreibt Client 1 lautlos, weil die Requests nacheinander kommen.','ETags schützen gerade auch den Zeitraum zwischen Lesen und späterem Schreiben.'],['Die bloße ETag-Anzeige gibt Client 2 immer Schreibvorrang.','Ein ETag ist eine Versionsvorbedingung, keine Prioritätszusage.']],0,sources.concurrency),
 Q('Nach einem Versionskonflikt soll der Client automatisch ohne Vorbedingung erneut schreiben. Warum ist das problematisch?', [['Es garantiert eine vollständige fachliche Zusammenführung.','Ohne Vergleich werden konkurrierende Eingaben nicht automatisch zusammengeführt.'],['Es kann den Schutz vor Lost Updates bewusst umgehen.','Neu lesen und fachlich entscheiden ist etwas anderes als blind überschreiben.'],['Es verhindert, dass irgendein Benutzer die Daten erneut lesen kann.','Ein solcher Lesestopp folgt nicht aus dem Entfernen der Vorbedingung.']],1,sources.concurrency)]},
 {id:'abap-m13-l1',title:'Erweiterungsbudget statt privater UI5-Hooks',sourceKeys:['extensions','sideEffects'],text:'Jede zusätzliche UI-Extension besitzt Lebenszyklus-, Test- und Upgradeaufwand. Prüfe zuerst Standardverhalten, Annotation und Konfiguration. Erst dann dokumentierte Extension APIs verwenden. OData-V2- und V4-Beispiele nicht vermischen; auch Methodensignaturen hängen von der verwendeten SAPUI5-Version ab. Requests abbrechen oder Ergebnisse gegen den aktuellen Kontext prüfen, wenn Benutzer schnell navigieren.',tip:'Ein Upgrade-Test braucht auch langsames Netz, Objektwechsel, Fehlermeldung und Tastaturpfad. Nur ein Screenshot im Happy Path sagt wenig über den Lifecycle.',cases:['Standardannotation löst den Anwendungsfall ohne privaten Hook.','Langsame Antwort nach Navigation wird verworfen oder passend zugeordnet.','Verwendete API fehlt in Zielversion: unterstützte Alternative statt Zugriff auf Interna.'],quiz:[
 Q('Ein Codebeispiel für Fiori Elements V2 soll in eine V4-App kopiert werden. Was prüfst du vor der Übernahme?', [['Nur, ob dieselbe Schriftart in beiden Screenshots vorkommt.','Darstellung beweist keine API-Kompatibilität.'],['Ob man private Controller mit gleichem Namen im Debugger findet.','Private Namen sind kein verlässlicher öffentlicher Erweiterungsvertrag.'],['Protokollmodell, dokumentierte API und unterstützte SAPUI5-Version.','V2/V4 und Release beeinflussen Erweiterungsmodell und verfügbare Methoden.']],2,sources.extensions),
 Q('Eine langsame Extension-Abfrage für Objekt A kommt erst nach Navigation zu B zurück. Was muss der Code verhindern?', [['Dass A sein Ergebnis in den aktuellen B-Kontext schreibt.','Das Ergebnis muss zum noch gültigen Kontext gehören oder verworfen werden.'],['Dass das Backend den aktuellen Benutzer weiterhin autorisiert.','Autorisierung bleibt notwendig; sie löst das clientseitige Kontextproblem nicht.'],['Dass irgendein asynchroner Request jemals fehlschlagen darf.','Fehler sind zu behandeln, nicht durch eine unrealistische Garantie auszuschließen.']],0,sources.extensions)]},
 {id:'abap-m15-l2',title:'Berechtigungstraces gezielt statt pauschaler Vollrechte',sourceKeys:['auth','launchpad'],text:'Reproduziere den abgelehnten Fachvorgang mit dem betroffenen Benutzer im richtigen System und Mandanten. Erfasse die erste relevante Ablehnung und prüfe passende Rollenwerte. SU53 und Berechtigungstraces sind Werkzeuge unterstützter klassischer Landschaften, keine universellen Apps in jeder Cloud-Edition. Eine leere Liste kann ein korrekter Datenfilter sein; ein 403 kann bereits aus einer vorgelagerten Schicht kommen.',tip:'Keine Dauerlösung mit SAP_ALL oder gemeinsamem Entwicklerkonto. Korrigiere nur nachgewiesene notwendige Rechte und teste anschließend erneut, was weiterhin verboten bleiben muss.',cases:['Erlaubter Buchungskreis funktioniert mit minimalen Rechten.','Leere berechtigte Ergebnismenge wird nicht als technischer Fehler missverstanden.','Fremder Kreis bleibt nach Rollenfix weiterhin gesperrt.'],quiz:[
 Q('Ein Benutzer sieht nach einem Rollenfix seine eigenen Belege. Welche Regression ist für den Sicherheitsnachweis besonders wichtig?', [['Der Entwickler kann mit Adminrechten noch mehr Belege lesen.','Das prüft nicht die Grenze des betroffenen Fachbenutzers.'],['Derselbe Fachbenutzer kann fremde Belege weiterhin nicht lesen.','Ein Fix darf notwendige Rechte ergänzen, ohne den verbotenen Bereich zu öffnen.'],['Die Kacheln werden nun in einer anderen Reihenfolge angezeigt.','Layoutreihenfolge ist kein negativer Autorisierungstest.']],1,sources.auth),
 Q('Ein Fachbenutzer bekommt 403; im Backend ist kein passender Request sichtbar. Was ist eine sinnvolle Diagnose?', [['Sofort alle DCL-Objekte des Backends entfernen.','Ohne Ankunft im Backend ist dessen DCL nicht als Ursache belegt.'],['Dem Benutzer pauschal einen gemeinsamen Superuser geben.','Das umgeht Grenzen und lokalisiert den Fehler nicht.'],['Vorgelagerte Auth-/Routinggrenzen und das antwortende System prüfen.','Die Ablehnung kann schon in Proxy, App oder Servicezugang entstehen.']],2,sources.auth)]},
 {id:'abap-m16-l2',title:'ATC-Gates mit Abhängigkeiten und Rückfallplan',sourceKeys:['migration','clean'],text:'Ein Git-Merge ist kein erfolgreich importierter Transport. Prüfe Abhängigkeiten von DDIC/CDS, Behavior, Service, UI und berechtigungsrelevanter Konfiguration. Für jede Zielumgebung braucht die Pipeline die passende Toolunterstützung, Prüfvariante und Freigabe. Ein grüner ATC-Lauf ersetzt weder Integration noch fachlichen Smoke Test. Rückfall kann bei bereits geänderten Daten eine Vorwärtskorrektur erfordern; ein alter Codeimport ist kein Datenbank-Undo.',tip:'Releaseprotokoll: Revision, Zielsystem, Objekt-/Konfigurationsabhängigkeiten, tatsächliche Importergebnisse, Smoke Test, Owner und Rückfallentscheidung.',cases:['Konsistente Artefaktversionen in Test importieren und Fachpfad prüfen.','Neue UI mit altem Service: Kompatibilität vor Freigabe erkennen.','Importfehler oder inkompatible Datenänderung stoppt Release statt automatischem Weiterlaufen.'],quiz:[
 Q('Git-Merge und ATC sind grün, der Zielsystemimport ist fehlgeschlagen. Welcher Status ist ehrlich?', [['Quellprüfung erfolgreich, Bereitstellung im Ziel noch fehlgeschlagen.','Prüfung des Codes und tatsächlicher Import sind getrennte Schritte.'],['Produktionsrelease vollständig abgeschlossen, weil Git grün ist.','Das ignoriert den beobachteten Importfehler.'],['Alle Fachprozesse im Ziel wurden dadurch automatisch getestet.','Ein Merge führt keine vollständigen Geschäftsprozesstests aus.']],0,sources.migration),
 Q('Ein Release hat persistierte Daten verändert. Genügt ein alter Codeimport als garantierter Rollback?', [['Ja, jede Datenänderung wird dadurch automatisch rückgängig gemacht.','Codehistorie kontrolliert nicht rückwirkend alle persistierten Fachzustände.'],['Ja, sobald der alte Git-Commit ohne Konflikt ausgecheckt werden kann.','Lokaler Versionswechsel belegt kein Daten-Undo im Zielsystem.'],['Nein, Datenverträglichkeit und Rückfall-/Vorwärtskorrektur separat planen.','Der Wiederherstellungsweg muss zum tatsächlichen Datenzustand passen.']],2,sources.migration)]},
 {id:'abap-m17-l1',title:'SAP LUW und RAP-Transaktionshoheit auseinanderhalten',sourceKeys:['eml','jobs'],text:'Klassische SAP LUW, Datenbank-LUW und RAP Save Sequence sind verwandte, aber nicht austauschbare Konzepte. Die Fachtransaktion legt fest, wer den Abschluss steuert. Eine wiederverwendete Routine mit implizitem oder explizitem Commit kann den RAP-Ablauf verletzen. Ein externer HTTP-Erfolg ist nicht durch lokales Rollback rückholbar; solche Integrationen brauchen einen eigenen Konsistenzvertrag.',tip:'Vor der Wiederverwendung eines alten BAPI-/RFC-Wrappers nicht nur Signatur prüfen: Commitverhalten, Locks, Berechtigung, Fehlerkanal und Freigabestatus gehören dazu.',cases:['Äußerer EML-Consumer steuert Save und prüft späte Fehler.','Behavior-Handler enthält keine eigene Commitsteuerung.','Remote Wirkung vor lokaler Ablehnung: Abgleich/Kompensation statt falscher Rollbackzusage.'],quiz:[
 Q('Eine alte Hilfsroutine führt selbst COMMIT WORK aus und soll aus einem RAP-Handler aufgerufen werden. Was muss vor Wiederverwendung geprüft werden?', [['Nur die Reihenfolge der Parameter im Pretty Printer.','Formatierung löst das Transaktionsrisiko nicht.'],['Commitverhalten und Eignung für den RAP-Transaktionskontext.','Ein fremdes Commit kann die vom Framework kontrollierte Fachtransaktion aufbrechen.'],['Ob ein zusätzlicher Commit im Handler die Routine noch sicherer macht.','Zusätzliche eigenmächtige Commits verschärfen den Konflikt.']],1,sources.eml),
 Q('Ein Remote-System hat eine Buchung bestätigt, danach scheitert lokal eine Validierung. Was bewirkt das lokale Rollback sicher nicht?', [['Es verwirft noch nicht gesicherte lokale Änderungen nach lokalem Vertrag.','Das kann gerade Teil der lokalen Fehlerbehandlung sein.'],['Es erlaubt eine getrennte Analyse des lokalen Fehlerzustands.','Die Analyse ist möglich, auch wenn die Remote-Wirkung bereits besteht.'],['Es nimmt die bereits bestätigte fremde Buchung automatisch zurück.','Fremde Seiteneffekte benötigen einen eigenen Abgleich- oder Kompensationsvertrag.']],2,sources.jobs)]},
 {id:'abap-m19-l2',title:'Remote-Verträge: Retrybudget, Zeitgrenzen und bereinigte Diagnose',sourceKeys:['connectivity','jobs'],text:'Behandle Verbindungsfehler, Authentifizierungsfehler und fachliche Ablehnungen getrennt. Definiere Timeout und maximale Antwortgröße; ein nicht empfangener Response beweist nicht, dass das Ziel keine Wirkung hatte. Mutierende Requests nur bei geeignetem Idempotenzvertrag wiederholen. Kommunikationskonfiguration und Secrets gehören in die vorgesehene Systemverwaltung, nicht in ABAP-Quelltext oder Frontenddateien.',tip:'Ein Supportprotokoll braucht Status, Zeitpunkt, Ziel/Operation und Korrelations-ID. Authorization-Header und vollständige Payloads schwärzen; Fehlersuche schafft keine neue Uploadfreigabe.',cases:['Erfolgreichen Zielrequest mit begrenzter Zeit und geprüfter Antwort verarbeiten.','Große Antwort oder Timeout kontrolliert abbrechen und Ausgang als unklar markieren.','401/403 oder fachlicher 4xx wird nicht unbegrenzt mit identischen Daten wiederholt.'],quiz:[
 Q('Ein mutierender Remote-Request läuft in einen Timeout. Welche Aussage ist sicher?', [['Der Ausgang kann unklar sein; vor Retry den Idempotenzvertrag prüfen.','Die Zielwirkung kann vor dem verlorenen Response bereits eingetreten sein.'],['Das Ziel hat garantiert keine Daten geändert.','Ein fehlender Response ist kein Beweis für ausgebliebene Verarbeitung.'],['Ein neuer Schlüssel pro Retry verhindert sicher alle Duplikate.','Wechselnde Schlüssel können die Deduplizierung gerade umgehen.']],0,sources.jobs),
 Q('Für ein BTP-Supportticket wird ein HTTP-Trace exportiert. Welche Daten sind vor Weitergabe zu entfernen?', [['Nur die öffentlichen Namen der HTTP-Methoden.','GET oder POST sind keine Secrets; ihre Entfernung löst das eigentliche Risiko nicht.'],['Tokens, Cookies, Passwörter und nicht benötigte personenbezogene Inhalte.','Diagnose muss Datenminimierung und Geheimnisschutz auch bei technischen Traces einhalten.'],['Nur die Zeilen mit erfolgreichen Statuscodes.','Secrets und private Inhalte können in Erfolgs- wie Fehlerrequests vorkommen.']],1,sources.connectivity)]}
];

export const existingQuizRevisions=updates.flatMap(item=>item.quiz.map((q,index)=>({...q,lesson:item.id,index})));
export const newQuizRevisions=lessons.flatMap(item=>item.quiz.map((q,index)=>({...q,lesson:item.id,index})));
